section.sourcecode:
ext-HashOfRootKey EXTENSION ::= {    -- Only in Root CA certificates
   SYNTAX         HashedRootKey
   IDENTIFIED BY  id-ce-hashOfRootKey
   CRITICALITY    {FALSE} }

HashedRootKey ::= SEQUENCE {
   hashAlg        HashAlgorithm,        -- Hash algorithm used
   hashValue      OCTET STRING }        -- Hash of DER-encoded
                                        --   SubjectPublicKeyInfo

id-ce-hashOfRootKey  ::=  OBJECT IDENTIFIER { 1 3 6 1 4 1 51483 2 1 }

HashedRootKeyCertExtn { 1 3 6 1 4 1 51483 0 1 }
DEFINITIONS IMPLICIT TAGS ::= BEGIN
-- EXPORTS All
IMPORTS
HashAlgorithm FROM PKIX1-PSS-OAEP-Algorithms-2009 -- RFC 5912 { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkix1-rsa-pkalgs-02(54) }
EXTENSION FROM PKIX-CommonTypes-2009 -- RFC 5912 { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkixCommon-02(57) } ;
-- -- Expand the certificate extensions list in RFC 5912 --
CertExtensions EXTENSION ::= { ext-HashOfRootKey, ... }
-- -- HashOfRootKey Certificate Extension --
ext-HashOfRootKey EXTENSION ::= { -- Only in Root CA certificates SYNTAX HashedRootKey IDENTIFIED BY id-ce-hashOfRootKey CRITICALITY {FALSE} }
HashedRootKey ::= SEQUENCE { hashAlg HashAlgorithm, -- Hash algorithm used hashValue OCTET STRING } -- Hash of DER-encoded -- SubjectPublicKeyInfo
id-ce-hashOfRootKey OBJECT IDENTIFIER ::= { 1 3 6 1 4 1 51483 2 1 }
END
